def invert_mapping(d):
    # AI-REFACTOR: Convert to dictionary comprehension preserving value-to-key mapping.
    res = {}
    for k, v in d.items():
        res[v] = k
    return res

validation_test:
def test_invert_mapping():
    assert invert_mapping({"a": 1, "b": 2}) == {1: "a", 2: "b"}
    assert invert_mapping({}) == {}

